<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Kubernetes Documentation</title>
    <style>
        :root {
            --kubernetes-blue: #326ce5;
            --text-color: #333333;
            --light-gray: #f8f9fa;
            --border-color: #e5e5e5;
            --sidebar-bg: #ffffff;
            --code-bg: #f4f5f7;
            --option-bg: #f0f2f5;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            color: var(--text-color);
            line-height: 1.5;
            font-size: 15px;
            background-color: #ffffff;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        /* Header */
        header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 24px;
            height: 64px;
            border-bottom: 1px solid var(--border-color);
            background-color: #ffffff;
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header-left {
            display: flex;
            align-items: center;
            gap: 24px;
        }

        .logo-container {
            display: flex;
            align-items: center;
            font-weight: 700;
            font-size: 22px;
            color: var(--kubernetes-blue);
            letter-spacing: -0.5px;
        }

        .logo-placeholder {
            width: 32px;
            height: 32px;
            background-color: var(--kubernetes-blue);
            mask-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10"/></svg>');
            -webkit-mask-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10"/></svg>');
            margin-right: 8px;
            clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
        }

        .main-nav {
            display: flex;
            gap: 20px;
            font-weight: 600;
            font-size: 14px;
        }

        .main-nav a:hover {
            color: var(--kubernetes-blue);
        }

        .header-right {
            display: flex;
            gap: 20px;
            font-weight: 600;
            font-size: 14px;
        }

        .dropdown::after {
            content: '▾';
            margin-left: 4px;
            font-size: 12px;
        }

        /* Layout */
        .layout-container {
            display: flex;
            max-width: 1600px;
            margin: 0 auto;
            min-height: calc(100vh - 64px);
        }

        /* Left Sidebar */
        .sidebar-left {
            width: 280px;
            flex-shrink: 0;
            border-right: 1px solid var(--border-color);
            background-color: #fafafa;
            padding: 20px 0;
            overflow-y: auto;
        }

        .search-container {
            padding: 0 20px;
            margin-bottom: 20px;
        }

        .search-box {
            display: flex;
            align-items: center;
            border: 1px solid #d1d5db;
            background-color: #ffffff;
            padding: 8px 12px;
            border-radius: 4px;
        }

        .search-box input {
            border: none;
            outline: none;
            width: 100%;
            margin-left: 8px;
            font-size: 14px;
        }

        .nav-menu {
            list-style: none;
            font-size: 14px;
        }

        .nav-menu li {
            padding: 4px 20px;
        }

        .nav-menu a {
            display: block;
            padding: 2px 0;
        }

        .nav-menu a:hover {
            color: var(--kubernetes-blue);
        }

        .nav-menu .caret {
            display: inline-block;
            width: 16px;
            color: #6b7280;
            font-size: 10px;
        }

        .nav-menu .caret-down {
            color: var(--kubernetes-blue);
        }

        .indent-1 { padding-left: 36px !important; }
        .indent-2 { padding-left: 52px !important; }
        .indent-3 { padding-left: 68px !important; }
        .indent-4 { padding-left: 84px !important; }

        .active-item {
            font-weight: 700;
            color: #111827;
        }

        /* Main Content */
        .main-content {
            flex-grow: 1;
            padding: 40px 60px;
            max-width: 960px;
        }

        .content-card {
            border: 1px solid var(--border-color);
            background-color: #fafafa;
            padding: 24px;
            margin-bottom: 30px;
        }

        .option-block {
            background-color: var(--option-bg);
            padding: 10px 16px;
            border-radius: 4px;
            font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
            font-size: 14px;
            color: #111827;
            margin-top: 24px;
            margin-bottom: 12px;
        }

        .option-block:first-child {
            margin-top: 0;
        }

        .option-desc {
            margin-bottom: 16px;
            padding-left: 16px;
            color: #374151;
        }

        h1 {
            font-size: 32px;
            font-weight: 400;
            margin: 40px 0 16px 0;
            color: #111827;
        }

        h2 {
            font-size: 22px;
            font-weight: 400;
            margin: 32px 0 16px 0;
            color: #111827;
        }

        .main-content p {
            margin-bottom: 16px;
            color: #374151;
        }

        .tab-button {
            display: inline-block;
            padding: 10px 24px;
            border: 1px solid var(--border-color);
            border-bottom: none;
            background-color: #fafafa;
            border-radius: 4px 4px 0 0;
            font-family: ui-monospace, SFMono-Regular, monospace;
            font-size: 14px;
            position: relative;
            top: 1px;
            color: #111827;
        }

        .card-attached {
            border-top-left-radius: 0;
            margin-top: 0;
        }

        .code-block {
            background-color: var(--code-bg);
            padding: 16px;
            border-radius: 4px;
            font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
            font-size: 13px;
            overflow-x: auto;
            white-space: pre;
            border: 1px solid #e5e7eb;
            margin-bottom: 24px;
            color: #111827;
        }

        .code-comment {
            color: #6b7280;
        }

        /* Right Sidebar */
        .sidebar-right {
            width: 260px;
            flex-shrink: 0;
            padding: 32px 20px;
            border-left: 1px solid var(--border-color);
            font-size: 13px;
        }

        .action-links {
            list-style: none;
            margin-bottom: 32px;
        }

        .action-links li {
            margin-bottom: 12px;
        }

        .action-links a {
            color: var(--kubernetes-blue);
            display: flex;
            align-items: center;
        }

        .action-links a:hover {
            text-decoration: underline;
        }

        .icon-placeholder {
            margin-right: 8px;
            font-size: 16px;
            display: inline-block;
            width: 16px;
            text-align: center;
        }

        .toc {
            list-style: none;
            border-left: 2px solid #e5e7eb;
            padding-left: 16px;
        }

        .toc li {
            margin-bottom: 12px;
            line-height: 1.4;
        }

        .toc a {
            color: #6b7280;
        }

        .toc a:hover {
            color: var(--kubernetes-blue);
        }
    </style>
</head>
